# alpha has order 6, not 26. Need to find a primitive element.
# Let me try different elements

def gf27_mul(a, b):
    a0, a1, a2 = a
    b0, b1, b2 = b
    c0 = (a0*b0 + 2*a1*b2 + 2*a2*b1) % 3
    c1 = (a0*b1 + a1*b0 + 2*a2*b2) % 3
    c2 = (a0*b2 + a1*b1 + a2*b0) % 3
    return (c0, c1, c2)

def gf27_pow(a, exp):
    result = (1, 0, 0)
    base = a
    while exp > 0:
        if exp % 2 == 1:
            result = gf27_mul(result, base)
        base = gf27_mul(base, base)
        exp //= 2
    return result

# Try all non-zero elements to find primitive ones
for a0 in range(3):
    for a1 in range(3):
        for a2 in range(3):
            if (a0, a1, a2) == (0, 0, 0):
                continue
            elem = (1, 0, 0)
            order = 0
            for i in range(1, 27):
                elem = gf27_mul(elem, (a0, a1, a2))
                if elem == (1, 0, 0):
                    order = i
                    break
            if order == 26:
                print(f"Primitive element: ({a0}, {a1}, {a2})")
                break
